message.content:
I need to compute the exact ioctl numbers for the ppdev ioctls on amd64 and 386 architectures. Please write and run a C program that prints the decimal values of all these ioctl constants. The program should include the actual Linux headers.

Create and run this program:

```c
#include <stdio.h>
#include <linux/ppdev.h>
#include <linux/parport.h>
#include <sys/time.h>

int main() {
    printf("PPSETMODE = %u\n", (unsigned)PPSETMODE);
    printf("PPRSTATUS = %u\n", (unsigned)PPRSTATUS);
    printf("PPRCONTROL = %u\n", (unsigned)PPRCONTROL);
    printf("PPWCONTROL = %u\n", (unsigned)PPWCONTROL);
    printf("PPRDATA = %u\n", (unsigned)PPRDATA);
    printf("PPWDATA = %u\n", (unsigned)PPWDATA);
    printf("PPCLAIM = %u\n", (unsigned)PPCLAIM);
    printf("PPRELEASE = %u\n", (unsigned)PPRELEASE);
    printf("PPYIELD = %u\n", (unsigned)PPYIELD);
    printf("PPFCONTROL = %u\n", (unsigned)PPFCONTROL);
    printf("PPEXCL = %u\n", (unsigned)PPEXCL);
    printf("PPDATADIR = %u\n", (unsigned)PPDATADIR);
    printf("PPNEGOT = %u\n", (unsigned)PPNEGOT);
    printf("PPWCTLONIRQ = %u\n", (unsigned)PPWCTLONIRQ);
    printf("PPCLRIRQ = %u\n", (unsigned)PPCLRIRQ);
    printf("PPSETPHASE = %u\n", (unsigned)PPSETPHASE);
    printf("PPGETTIME = %u\n", (unsigned)PPGETTIME);
    printf("PPSETTIME = %u\n", (unsigned)PPSETTIME);
    printf("PPGETMODES = %u\n", (unsigned)PPGETMODES);
    printf("PPGETMODE = %u\n", (unsigned)PPGETMODE);
    printf("PPGETPHASE = %u\n", (unsigned)PPGETPHASE);
    printf("PPGETFLAGS = %u\n", (unsigned)PPGETFLAGS);
    printf("PPSETFLAGS = %u\n", (unsigned)PPSETFLAGS);

    printf("\n--- IEEE 1284 modes ---\n");
    printf("IEEE1284_MODE_NIBBLE = %u\n", IEEE1284_MODE_NIBBLE);
    printf("IEEE1284_MODE_BYTE = %u\n", IEEE1284_MODE_BYTE);
    printf("IEEE1284_MODE_COMPAT = %u\n", IEEE1284_MODE_COMPAT);
    printf("IEEE1284_MODE_BECP = %u\n", IEEE1284_MODE_BECP);
    printf("IEEE1284_MODE_ECP = %u\n", IEEE1284_MODE_ECP);
    printf("IEEE1284_MODE_ECPRLE = %u\n", IEEE1284_MODE_ECPRLE);
    printf("IEEE1284_MODE_ECPSWE = %u\n", IEEE1284_MODE_ECPSWE);
    printf("IEEE1284_MODE_EPP = %u\n", IEEE1284_MODE_EPP);
    printf("IEEE1284_MODE_EPPSL = %u\n", IEEE1284_MODE_EPPSL);
    printf("IEEE1284_MODE_EPPSWE = %u\n", IEEE1284_MODE_EPPSWE);
    printf("IEEE1284_DEVICEID = %u\n", IEEE1284_DEVICEID);
    printf("IEEE1284_EXT_LINK = %u\n", IEEE1284_EXT_LINK);
    printf("IEEE1284_ADDR = %u\n", IEEE1284_ADDR);
    printf("IEEE1284_DATA = %u\n", IEEE1284_DATA);

    printf("\n--- PP flags ---\n");
    printf("PP_FASTWRITE = %u\n", PP_FASTWRITE);
    printf("PP_FASTREAD = %u\n", PP_FASTREAD);
    printf("PP_W91284PIC = %u\n", PP_W91284PIC);
    printf("PP_FLAGMASK = %u\n", PP_FLAGMASK);

    printf("\n--- Parport modes ---\n");
    printf("PARPORT_MODE_PCSPP = %u\n", PARPORT_MODE_PCSPP);
    printf("PARPORT_MODE_TRISTATE = %u\n", PARPORT_MODE_TRISTATE);
    printf("PARPORT_MODE_EPP = %u\n", PARPORT_MODE_EPP);
    printf("PARPORT_MODE_ECP = %u\n", PARPORT_MODE_ECP);
    printf("PARPORT_MODE_COMPAT = %u\n", PARPORT_MODE_COMPAT);
    printf("PARPORT_MODE_DMA = %u\n", PARPORT_MODE_DMA);
    printf("PARPORT_MODE_SAFEININT = %u\n", PARPORT_MODE_SAFEININT);

    return 0;
}
```

Compile with `gcc -o /tmp/ppdev_consts /tmp/ppdev_consts.c` and run it. This gives us amd64 values.

Then also compile for 32-bit to get i386 values:
`gcc -m32 -o /tmp/ppdev_consts32 /tmp/ppdev_consts.c` and run it.

The main difference will be in PPGETTIME and PPSETTIME because struct timeval has different sizes on 32-bit vs 64-bit.

